/** The longest annotation text, in characters. */
export const MAX_ANNOTATION_TEXT_LENGTH = 10_000;

/**
 * What a person writes in an annotation. `entityId` names the annotated
 * entity of the Landscape; an annotation without one is free.
 */
export type AnnotationContent = {
  entityId?: string;
  title: string;
  text: string;
};

/** One annotation of the creator, handed over to a new Room as it is. */
export type StartingAnnotation = AnnotationContent & {
  /** A positive whole number, unique among the creator's annotations. */
  id: number;
  creatorName: string;
  lastEditorName: string;
};

/** The service's answer to an "annotationAdd" request: the annotation's id. */
export type AnnotationAdded = { id: number };

/**
 * Reasons with which the service rejects an "annotationAdd" request. The SDK
 * rejects `room.request(...)` with an error whose `reason` is one of these.
 */
export const AnnotationRefusal = {
  /** The payload is malformed, or the title or text is too long. */
  INVALID: "invalid",
} as const;
export type AnnotationRefusal = (typeof AnnotationRefusal)[keyof typeof AnnotationRefusal];

/**
 * Messages a client sends to the Room: message type -> payload.
 * Each entry has a handler of the same name in CollaborationRoom's `messages`.
 */
export type ClientMessages = {
  /** Host only: removes the Participant with this session id from the Room. */
  kick: { sessionId: string };
  /** Host only: makes the Participant with this session id the Host instead. */
  handOverHost: { sessionId: string };
  /** Changes the sender's own color to a CSS hex color such as "#e6194b". Other values are ignored. */
  setColor: { color: string };
  /** Post a chat message. Rejected with a ChatRefusal (e.g. "muted"). */
  chatSend: { text: string };
  /** Delete a chat entry for everyone. Allowed for its author and the Host. */
  chatDelete: { entryId: string };
  /** Mute or unmute a Participant (by session id). Host only. */
  chatMute: { participantId: string; muted: boolean };
  /** Follow another Participant's camera (their session id), or stop with null. */
  spectate: { target: string | null };
  /**
   * The sender's camera, sent only while somebody spectates them, at most
   * CAMERA_UPDATES_PER_SECOND times per second and only when it changed.
   */
  camera: CameraPose;
  /** The sender entered the immersive view of this entity, or left it with null. */
  immersive: { entityId: string | null };
  /**
   * Host only: the Room explores this Landscape (a Landscape token value)
   * from now on. Clears everything tied to the old Landscape.
   */
  switchLandscape: { landscapeToken: string };
  /** One user action on the Districts (see DistrictAction). */
  districts: DistrictAction[];
  /** Host only: switches the District sharing option (see DistrictSharing). */
  districtSharing: DistrictSharing;
  /** Shares the sender's popup of this entity: everyone in the Room has it open from now on. */
  sharePopup: { entityId: string };
  /** Closes the shared popup of this entity for everyone. Allowed for any Participant. */
  closePopup: { entityId: string };
  /**
   * A request: makes a new annotation, by the sender. Answered with its
   * AnnotationAdded id; for an entity that already has one, with the id of
   * that one, and nothing changes. Rejected with an AnnotationRefusal.
   */
  annotationAdd: AnnotationContent;
  /** Saves an annotation's title and text, with the sender as last editor. Sent on save, not per keystroke. */
  annotationEdit: { id: number; title: string; text: string };
  /** Removes an annotation for everyone. */
  annotationRemove: { id: number };
};

/**
 * Messages the Room sends to clients: message type -> payload.
 */
export type ServerMessages = {
  /** The camera of the Participant `from`, forwarded only to those who spectate them. */
  camera: CameraPose & { from: string };
};

/** A camera as world-space pose plus the column-major 4x4 projection matrix (as three.js `toArray()`). */
export type CameraPose = {
  position: [number, number, number];
  quaternion: [number, number, number, number];
  projection: number[];
};

/** How often a spectated Participant sends its camera at most. */
export const CAMERA_UPDATES_PER_SECOND = 30;

